"""Risk indicator and rule models for ExitLens."""

from enum import Enum
from typing import List, Optional

from pydantic import BaseModel, ConfigDict, Field

from app.schemas.common import ProvenanceKind


class RiskSeverity(str, Enum):
    """Standardized severity tiers for risk rules."""
    CRITICAL = "CRITICAL"
    HIGH = "HIGH"
    MEDIUM = "MEDIUM"
    LOW = "LOW"
    INFO = "INFO"


class RiskIndicator(BaseModel):
    """An evidence-backed finding generated by deterministic maintenance rules."""
    model_config = ConfigDict(extra="ignore")

    rule_id: str = Field(
        ...,
        description="Stable rule identifier, e.g. UNPINNED_OR_WIDE_CONSTRAINT, MANIFEST_LOCK_DRIFT",
    )
    provenance: ProvenanceKind = Field(
        default=ProvenanceKind.INFERRED,
        description="Provenance of the risk indicator (always INFERRED for deterministic rules)",
    )

    severity: RiskSeverity = Field(..., description="Severity classification")
    title: str = Field(..., description="Short descriptive title of the finding")
    signal: Optional[str] = Field(default=None, description="Alias for title or rule finding signal")
    explanation: str = Field(..., description="Detailed, explainable reasoning for the risk indicator")
    signal_source: str = Field(
        ...,
        description="Where signal originated (e.g. manifest, lockfile, ast_mapping, environment)",
    )
    evidence_refs: List[str] = Field(
        default_factory=list,
        description="List of evidence_ids supporting this finding",
    )
    evidence_ids: List[str] = Field(
        default_factory=list,
        description="Alias for evidence_refs",
    )
    confidence: Optional[str] = Field(
        default=None,
        description="Confidence level or limitation notes (e.g. 'high', 'review-only')",
    )
    limitations: Optional[str] = Field(
        default=None,
        description="Explicit limitations of the signal or rule context",
    )
